<style>
    :root{--dv-primary:#0d6efd;--dv-bg:#f6f8fc;--dv-card:#fff;--dv-text:#0f172a;--dv-muted:#64748b;--dv-border:rgba(15,23,42,.08);--dv-shadow:0 18px 45px rgba(2,6,23,.10);--dv-radius:18px;}
    .dv-page{background:radial-gradient(1200px 650px at 15% -10%, rgba(13,110,253,.14), transparent 55%),radial-gradient(900px 520px at 90% 0%, rgba(14,165,233,.10), transparent 60%);border-radius:22px;padding:18px;}
    .dv-head{background:linear-gradient(90deg, rgba(13,110,253,0.12), rgba(248,250,252,1));border:1px solid rgba(15,23,42,0.06);border-radius:18px;padding:16px;box-shadow:0 10px 30px rgba(2,6,23,0.06);position:relative;overflow:hidden;margin-bottom:14px;}
    .dv-head:before{content:"";position:absolute;left:0;top:0;bottom:0;width:6px;background:linear-gradient(180deg,#0d6efd,#6ea8fe);border-radius:18px 0 0 18px;}
    .dv-title{font-weight:900;color:var(--dv-text);margin:0;}
    .dv-sub{color:var(--dv-muted);margin:0;}
    .dv-card{background:var(--dv-card);border:1px solid rgba(15,23,42,.06);border-radius:var(--dv-radius);box-shadow:var(--dv-shadow);overflow:hidden;}
    .dv-card-header{padding:14px 16px;background:linear-gradient(90deg,#0d6efd 0%,#6ea8fe 100%);color:#fff;display:flex;align-items:center;justify-content:space-between;gap:10px;}
    .dv-card-header .muted{color:rgba(255,255,255,.75);font-size:.9rem;}
    .dv-chip{display:inline-flex;align-items:center;gap:8px;padding:7px 12px;border-radius:999px;border:1px solid rgba(15,23,42,0.10);background:#fff;font-weight:800;font-size:.88rem;color:#0f172a;}
    .dv-table thead th{background:linear-gradient(90deg,#e3f2fd 0%,#f8fafc 100%);color:#0d6efd;font-weight:900;border-bottom:1px solid rgba(15,23,42,.08);padding:14px 16px;white-space:nowrap;}
    .dv-table tbody td{padding:14px 16px;vertical-align:middle;}
    .dv-table tbody tr:hover{background:rgba(13,110,253,.05);}
    .dv-btn{border-radius:999px;padding:8px 14px;font-weight:800;}
    .dv-form .form-label{font-weight:800;color:#0f172a;}
    .dv-form .form-control,.dv-form .form-select{border-radius:14px;padding:10px 12px;border:1px solid rgba(15,23,42,.12);}
    .dv-form .form-control:focus,.dv-form .form-select:focus{box-shadow:0 0 0 4px rgba(13,110,253,.12);border-color:rgba(13,110,253,.35);}
    .dv-multi{min-height:46px;}
</style>
